package io.knowledgebrain.activity;
import com.zaxxer.hikari.HikariDataSource;
public final class ActivityRebuild {
 public static void main(String[] args)throws Exception{var config=ActivityConfiguration.databaseOptions(System.getenv("BRAIN_ACTIVITY_DATABASE_URL"),System.getenv("BRAIN_ACTIVITY_DATABASE_PASSWORD"),null);config.setPoolName("activity-replay");try(var ds=new HikariDataSource(config)){var store=new ActivityStore(ds);var index=new ActivityClickHouse(System.getenv("BRAIN_ACTIVITY_CLICKHOUSE_ORIGIN"),System.getenv("BRAIN_ACTIVITY_TRUST_FILE"),"/clickhouse-projector");var source=new ActivitySnapshot(System.getenv("BRAIN_ACTIVITY_LEARNING_ORIGIN"),System.getenv("BRAIN_ACTIVITY_TRUST_FILE"),System.getenv("BRAIN_ACTIVITY_EXPORT_KEY"),System.getenv("BRAIN_ACTIVITY_PLANNING_ORIGIN"),System.getenv("BRAIN_ACTIVITY_PLANNING_EXPORT_KEY"),System.getenv("BRAIN_ACTIVITY_CONTENT_ORIGIN"),System.getenv("BRAIN_ACTIVITY_CONTENT_EXPORT_KEY"),System.getenv("BRAIN_ACTIVITY_KNOWLEDGE_ORIGIN"),System.getenv("BRAIN_ACTIVITY_KNOWLEDGE_EXPORT_KEY"),System.getenv("BRAIN_ACTIVITY_INTEGRATION_ORIGIN"),System.getenv("BRAIN_ACTIVITY_INTEGRATION_EXPORT_KEY"));store.startRebuild();source.backfill(store);long count=0;while(store.state().rebuilding()){var rows=store.pending(100);if(!rows.isEmpty()){index.applyAll(rows.stream().map(store::decode).toList());store.appliedAll(rows.stream().map(ActivityStore.Pending::eventId).toList());count+=rows.size();}store.finishIfDrained();}System.out.println("PASS canonical Learning/Planning/Content/Knowledge and durable Inbox timeline replay: "+count+" rows; source facts unchanged");}}
}
